func (sns *StablecoinNetworkSelect) Scan(ctx context.Context, v any) error {
	ctx = setContextOp(ctx, sns.ctx, ent.OpQuerySelect)
	if err := sns.prepareQuery(ctx); err != nil {
		return err
	}
	return scanWithInterceptors[*StablecoinNetworkQuery, *StablecoinNetworkSelect](ctx, sns.StablecoinNetworkQuery, sns, sns.inters, v)
}

func (sns *StablecoinNetworkSelect) sqlScan(ctx context.Context, root *StablecoinNetworkQuery, v any) error {
	selector := root.sqlQuery(ctx)
	aggregation := make([]string, 0, len(sns.fns))
	for _, fn := range sns.fns {
		aggregation = append(aggregation, fn(selector))
	}
	switch n := len(*sns.selector.flds); {
	case n == 0 && len(aggregation) > 0:
		selector.Select(aggregation...)
	case n != 0 && len(aggregation) > 0:
		selector.AppendSelect(aggregation...)
	}
	rows := &sql.Rows{}
	query, args := selector.Query()
	if err := sns.driver.Query(ctx, query, args, rows); err != nil {
		return err
	}
	defer rows.Close()
	return sql.ScanSlice(rows, v)
}
